from collections import deque
for conn in [4,8]:
  ds=[(1,0),(-1,0),(0,1),(0,-1)]
  if conn==8: ds += [(1,1),(1,-1),(-1,1),(-1,-1)]
  vis=set(); comps=[]
  for i in range(27):
    for j in range(13,23):
      c=g[i][j]
      if c==8 or (i,j) in vis: continue
      q=[(i,j)];vis.add((i,j)); pts=[]
      while q:
        a,b=q.pop(); pts.append((a,b))
        for di,dj in ds:
          x,y=a+di,b+dj
          if 0<=x<27 and 13<=y<23 and (x,y) not in vis and g[x][y]==c:
            vis.add((x,y));q.append((x,y))
      comps.append((c,len(pts),min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts),sorted(pts)))
  print('\nconn',conn)
  for x in comps: print(x[:6],x[6])

